-- Generated by Ergasterion from a product declaration. Do not edit by hand.
{{ config(materialized='table') }}

with
quarantined as (
    select
        valuation_id,
        vantora_fund_id,
        vantora_company_id,
        valuation_date,
        value_usd,
        method,
        valuation_level,
        confidence_score,
        violation_00,
        violation_01
    from {{ ref("investment__vantora_valuation__checked") }}
),
violations as (
    select
        'valuation_id_not_null' as rule_name,
        valuation_id,
        vantora_fund_id,
        vantora_company_id,
        valuation_date,
        value_usd,
        method,
        valuation_level,
        confidence_score
    from quarantined
    where violation_00

    union all

    select
        'valuation_date_not_null' as rule_name,
        valuation_id,
        vantora_fund_id,
        vantora_company_id,
        valuation_date,
        value_usd,
        method,
        valuation_level,
        confidence_score
    from quarantined
    where violation_01
)

select
    rule_name,
    valuation_id,
    vantora_fund_id,
    vantora_company_id,
    valuation_date,
    value_usd,
    method,
    valuation_level,
    confidence_score
from violations
